// Output 1: the answer to Whoobe (it keeps msg.res, which the "answer" node needs). Output 2: the event to process, only a real, fresh, authentic one.
const h = msg.req.headers;
const ts = Number(h['x-whoobe-timestamp'] || 0);
const ev = msg.payload || {};
const reply = (code, body) => { msg.statusCode = code; msg.payload = body; return [msg, null]; };
if (!ev.id || !ev.type) return reply(400, { ok: false, error: 'not an object event' });
if (Math.abs(Date.now() / 1000 - ts) > 300) return reply(400, { ok: false, error: 'timestamp too old' });
const secret = env.get('WHOOBE_SIGNING_SECRET');
if (secret) {
  // the body as Node-RED parsed it, written back the way Whoobe wrote it (compact JSON, same key order)
  const want = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + JSON.stringify(ev)).digest('hex');
  if (h['x-whoobe-signature'] !== want) return reply(401, { ok: false, error: 'bad signature' });
}
if (ev.test || !ev.object) return reply(200, { ok: true });
msg.statusCode = 200; msg.payload = { ok: true };
return [msg, { event: ev, payload: ev }];

// Write a note on the record. Idempotent on the event id: the same event twice writes the same text.
const ev = msg.event;
const n = (flow.get('seen') || {});
if (n[ev.id]) return null;          // already handled (Whoobe delivers at least once)
n[ev.id] = Date.now();
flow.set('seen', n);
msg.method = 'PATCH';
msg.url = env.get('WHOOBE_CLIENT_URL').replace(/\/+$/, '') + '/data/' + encodeURIComponent(ev.class.name) + '/' + ev.object.id;
msg.headers = { 'Authorization': 'Bearer ' + env.get('WHOOBE_KEY'), 'Content-Type': 'application/json' };
msg.payload = { attributes: { notes: 'processed by Node-RED (' + ev.type + ', event ' + ev.id.slice(0, 8) + ')' } };
return msg;
